import json
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum
from collections import defaultdict


class Category(Enum):
    GROCERIES = "groceries"
    ENTERTAINMENT = "entertainment"
    UTILITIES = "utilities"
    TRANSPORTATION = "transportation"
    DINING = "dining"
    HEALTHCARE = "healthcare"
    MISCELLANEOUS = "miscellaneous"


@dataclass
class Expense:
    """Represents a single expense entry."""
    user_id: str
    amount: float
    category: Category
    description: str = ""

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError("Expense amount cannot be negative.")
        if not isinstance(self.category, Category):
            raise TypeError("Category must be a Category enum.")


@dataclass
class BudgetLimit:
    """Budget limit for a specific category."""
    category: Category
    limit: float

    def __post_init__(self):
        if self.limit < 0:
            raise ValueError("Budget limit cannot be negative.")


class User:
    """Represents a user in the system."""
    def __init__(self, user_id: str, name: str):
        self.user_id = user_id
        self.name = name
        self.expenses: List[Expense] = []

    def add_expense(self, expense: Expense):
        """Add an expense to the user's record."""
        if expense.user_id != self.user_id:
            raise ValueError("Expense user_id must match the user's ID.")
        self.expenses.append(expense)

    def get_total_spending(self, category: Optional[Category] = None) -> float:
        """Get total spending, optionally filtered by category."""
        if category is None:
            return sum(e.amount for e in self.expenses)
        return sum(e.amount for e in self.expenses if e.category == category)

    def get_expenses_by_category(self) -> Dict[Category, float]:
        """Return spending aggregated by category."""
        totals = defaultdict(float)
        for expense in self.expenses:
            totals[expense.category] += expense.amount
        return dict(totals)


class MultiAgentBudgetOptimizer:
    """Main class for collaborative budget management and optimization."""
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budget_limits: Dict[Category, float] = {}
        self.group_expenses: List[Expense] = []  # For quick aggregation

    def add_user(self, user_id: str, name: str) -> User:
        """Add a new user to the system."""
        if user_id in self.users:
            raise ValueError(f"User with ID '{user_id}' already exists.")
        user = User(user_id, name)
        self.users[user_id] = user
        return user

    def remove_user(self, user_id: str):
        """Remove a user and their associated expenses."""
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        # Remove user's expenses from group tracking
        self.group_expenses = [e for e in self.group_expenses if e.user_id != user_id]
        del self.users[user_id]

    def add_expense(self, user_id: str, amount: float, category: Category, description: str = "") -> Expense:
        """Add an expense for a specific user."""
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        expense = Expense(user_id=user_id, amount=amount, category=category, description=description)
        self.users[user_id].add_expense(expense)
        self.group_expenses.append(expense)
        return expense

    def set_budget_limit(self, category: Category, limit: float):
        """Set or update the budget limit for a category."""
        if limit < 0:
            raise ValueError("Budget limit cannot be negative.")
        self.budget_limits[category] = limit

    def get_budget_limit(self, category: Category) -> Optional[float]:
        """Get the budget limit for a category (None if not set)."""
        return self.budget_limits.get(category)

    def get_group_total_spending(self, category: Optional[Category] = None) -> float:
        """Get total spending across all users."""
        if category is None:
            return sum(e.amount for e in self.group_expenses)
        return sum(e.amount for e in self.group_expenses if e.category == category)

    def get_remaining_budget(self, category: Optional[Category] = None) -> float:
        """Calculate remaining budget for a category or overall."""
        if category is None:
            total_budget = sum(self.budget_limits.values())
            total_spent = self.get_group_total_spending()
            return max(0.0, total_budget - total_spent)
        limit = self.get_budget_limit(category)
        if limit is None:
            return float('inf')
        spent = self.get_group_total_spending(category)
        return max(0.0, limit - spent)

    def get_user_contributions(self) -> Dict[str, Dict[str, float]]:
        """Return spending breakdown per user and per category."""
        contributions = {}
        for user_id, user in self.users.items():
            contributions[user_id] = {
                "name": user.name,
                "total": user.get_total_spending(),
                "by_category": user.get_expenses_by_category()
            }
        return contributions

    def get_dashboard_summary(self) -> Dict:
        """Generate a dashboard summary for the group."""
        summary = {
            "total_users": len(self.users),
            "total_spent": self.get_group_total_spending(),
            "total_budget": sum(self.budget_limits.values()),
            "remaining_budget": self.get_remaining_budget(),
            "by_category": {},
            "user_contributions": self.get_user_contributions()
        }
        for category in Category:
            spent = self.get_group_total_spending(category)
            limit = self.get_budget_limit(category)
            summary["by_category"][category.value] = {
                "spent": spent,
                "limit": limit,
                "remaining": self.get_remaining_budget(category)
            }
        return summary

    def _get_over_budget_categories(self) -> List[Category]:
        """Return list of categories where spending exceeds budget."""
        over_budget = []
        for category in Category:
            spent = self.get_group_total_spending(category)
            limit = self.get_budget_limit(category)
            if limit is not None and spent > limit:
                over_budget.append(category)
        return over_budget

    def suggest_optimizations(self) -> List[Dict]:
        """
        Suggest ways to reduce expenses or reallocate funds.
        Returns a list of actionable suggestions.
        """
        suggestions = []
        over_budget = self._get_over_budget_categories()

        if not over_budget and self.get_remaining_budget() >= 0:
            suggestions.append({
                "type": "positive",
                "message": "Group is within budget overall. Consider saving or investing surplus."
            })
            return suggestions

        # Analyze per-category overspending
        for category in over_budget:
            spent = self.get_group_total_spending(category)
            limit = self.get_budget_limit(category)
            excess = spent - limit
            suggestions.append({
                "type": "over_budget",
                "category": category.value,
                "message": f"Category '{category.value}' exceeded budget by ${excess:.2f}. "
                           f"Consider reducing discretionary spending (e.g., switching to generic brands, limiting entertainment)."
            })

        # Suggest reallocation from under-utilized categories
        for category in Category:
            spent = self.get_group_total_spending(category)
            limit = self.get_budget_limit(category)
            if limit is not None and spent < limit * 0.5:  # Used less than 50%
                unused = limit - spent
                suggestions.append({
                    "type": "reallocate",
                    "category": category.value,
                    "message": f"Category '{category.value}' has ${unused:.2f} unused budget. "
                               f"Consider reallocating to over-budget categories or savings."
                })

