from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum
import copy


class Category(Enum):
    GROCERIES = "groceries"
    ENTERTAINMENT = "entertainment"
    UTILITIES = "utilities"
    TRANSPORTATION = "transportation"
    HEALTHCARE = "healthcare"
    OTHER = "other"


@dataclass
class Expense:
    amount: float
    category: Category
    description: str
    user_id: str

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError("Expense amount cannot be negative.")
        if not isinstance(self.category, Category):
            raise TypeError("Category must be a Category enum value.")


@dataclass
class BudgetLimit:
    category: Category
    limit: float

    def __post_init__(self):
        if self.limit < 0:
            raise ValueError("Budget limit cannot be negative.")


@dataclass
class User:
    user_id: str
    name: str
    expenses: List[Expense] = field(default_factory=list)

    def add_expense(self, expense: Expense) -> None:
        if expense.user_id != self.user_id:
            raise ValueError("Expense user_id must match the user's ID.")
        self.expenses.append(expense)

    def get_total_spent(self) -> float:
        return sum(e.amount for e in self.expenses)

    def get_spent_by_category(self) -> Dict[Category, float]:
        result: Dict[Category, float] = {cat: 0.0 for cat in Category}
        for expense in self.expenses:
            result[expense.category] += expense.amount
        return result


class MultiAgentBudgetOptimizer:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budget_limits: Dict[Category, float] = {}
        self.group_savings_goal: Optional[float] = None

    def add_user(self, user_id: str, name: str) -> None:
        if user_id in self.users:
            raise ValueError(f"User with ID '{user_id}' already exists.")
        self.users[user_id] = User(user_id=user_id, name=name)

    def remove_user(self, user_id: str) -> None:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        del self.users[user_id]

    def set_budget_limit(self, category: Category, limit: float) -> None:
        if limit < 0:
            raise ValueError("Budget limit cannot be negative.")
        self.budget_limits[category] = limit

    def adjust_budget_limit(self, category: Category, new_limit: float) -> None:
        if category not in self.budget_limits:
            raise KeyError(f"No budget limit set for category '{category.value}'.")
        self.set_budget_limit(category, new_limit)

    def add_expense(self, user_id: str, amount: float, category: Category, description: str = "") -> None:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        expense = Expense(amount=amount, category=category, description=description, user_id=user_id)
        self.users[user_id].add_expense(expense)

    def get_total_group_expenses(self) -> float:
        return sum(user.get_total_spent() for user in self.users.values())

    def get_total_group_spent_by_category(self) -> Dict[Category, float]:
        result: Dict[Category, float] = {cat: 0.0 for cat in Category}
        for user in self.users.values():
            for cat, amount in user.get_spent_by_category().items():
                result[cat] += amount
        return result

    def get_remaining_budget(self) -> Dict[Category, float]:
        spent_by_cat = self.get_total_group_spent_by_category()
        remaining = {}
        for cat in Category:
            limit = self.budget_limits.get(cat, float('inf'))
            remaining[cat] = limit - spent_by_cat[cat]
        return remaining

    def get_user_summary(self, user_id: str) -> Dict:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        user = self.users[user_id]
        return {
            "user_id": user_id,
            "name": user.name,
            "total_spent": user.get_total_spent(),
            "expenses_by_category": user.get_spent_by_category(),
            "expense_count": len(user.expenses)
        }

    def get_group_summary(self) -> Dict:
        total_spent = self.get_total_group_expenses()
        spent_by_cat = self.get_total_group_spent_by_category()
        remaining_by_cat = self.get_remaining_budget()
        user_summaries = {
            uid: self.get_user_summary(uid) for uid in self.users
        }
        return {
            "total_spent": total_spent,
            "spent_by_category": spent_by_cat,
            "remaining_by_category": remaining_by_cat,
            "user_summaries": user_summaries,
            "user_count": len(self.users)
        }

    def set_savings_goal(self, goal: float) -> None:
        if goal < 0:
            raise ValueError("Savings goal cannot be negative.")
        self.group_savings_goal = goal

    def _get_over_budget_categories(self) -> List[Category]:
        spent_by_cat = self.get_total_group_spent_by_category()
        return [cat for cat in Category
                if cat in self.budget_limits and spent_by_cat[cat] > self.budget_limits[cat]]

    def _get_underutilized_categories(self) -> List[Category]:
        spent_by_cat = self.get_total_group_spent_by_category()
        return [cat for cat in Category
                if cat in self.budget_limits and spent_by_cat[cat] < 0.5 * self.budget_limits[cat]]

    def suggest_optimizations(self) -> List[Dict]:
        suggestions = []
        spent_by_cat = self.get_total_group_spent_by_category()
        remaining_by_cat = self.get_remaining_budget()

        # Over-budget categories: suggest reduction
        over_budget_cats = self._get_over_budget_categories()
        for cat in over_budget_cats:
            overage = spent_by_cat[cat] - self.budget_limits[cat]
            suggestions.append({
                "type": "over_budget",
                "category": cat.value,
                "overage": overage,
                "message": f"Category '{cat.value}' is over budget by ${overage:.2f}. Consider reducing spending."
            })

        # Underutilized categories: suggest reallocation
        underutilized_cats = self._get_underutilized_categories()
        for cat in underutilized_cats:
            unused = self.budget_limits[cat] - spent_by_cat[cat]
            suggestions.append({
                "type": "underutilized",
                "category": cat.value,
                "unused_amount": unused,
                "message": f"Category '{cat.value}' has ${unused:.2f} unused. Consider reallocating to over-budget categories or savings."
            })

        # Savings goal alignment
        if self.group_savings_goal is not None:
            total_spent = self.get_total_group_expenses()
            # Assume total income is fixed; savings = income - total_spent
            # Since income is unknown, estimate required reduction to meet goal
            # Simplified: suggest reducing total spending by at least the savings goal
            # (In real app, income would be required input)
            if total_spent > 0:
                required_reduction = min(self.group_savings_goal, total_spent * 0.5)  # cap at 50% of current spending
                suggestions.append({
                    "type": "savings_goal",
                    "savings_goal": self.group_savings_goal,
                    "required_reduction": required_reduction,
                    "message": f"To meet the group savings goal of ${self.group_savings_goal:.2f}, consider reducing total spending by at least ${required_reduction:.2f}."
                })

        return suggestions


