        self.users[user_id] = User(user_id=user_id, name=name)

    def remove_user(self, user_id: str) -> None:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        del self.users[user_id]

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    # --- Budget Management ---
    def set_budget_limit(self, category: Category, limit: float) -> None:
        if limit < 0:
            raise ValueError("Budget limit cannot be negative.")
        self.group_budget_limits[category] = limit
        if category in self.budgets:
            self.budgets[category].limit = limit

    def adjust_budget_limit(self, category: Category, delta: float) -> None:
        if category not in self.group_budget_limits:
            raise KeyError(f"Category '{category.value}' not found.")
        new_limit = self.group_budget_limits[category] + delta
        if new_limit < 0:
            raise ValueError("Adjusted budget limit cannot be negative.")
        self.set_budget_limit(category, new_limit)

    # --- Expense Management ---
    def add_expense(self, user_id: str, amount: float, category: Category,
                    description: str = "") -> Expense:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        if amount <= 0:
            raise ValueError("Expense amount must be positive.")

        expense = Expense(user_id=user_id, amount=amount, category=category,
                          description=description)
        self.users[user_id].add_expense(expense)
        self.budgets[category].update_spent(amount)
        return expense

    def get_user_expenses(self, user_id: str) -> List[Expense]:
        user = self.get_user(user_id)
        return user.expenses if user else []

    # --- Financial Summary ---
    def get_group_total_spent(self, category: Optional[Category] = None) -> float:
        if category is None:
            return sum(u.get_total_spent() for u in self.users.values())
        return self.budgets[category].current_spent

    def get_group_remaining_budget(self, category: Optional[Category] = None) -> float:
        if category is None:
            return sum(self.budgets[cat].remaining() for cat in Category)
        return self.budgets[category].remaining()

    def get_group_summary(self) -> Dict:
        total_spent = self.get_group_total_spent()
        total_budget = sum(self.group_budget_limits.values())
        remaining = total_budget - total_spent
        user_contributions = {
            uid: user.get_total_spent()
            for uid, user in self.users.items()
        }
        return {
            "total_spent": total_spent,
            "total_budget": total_budget,
            "remaining": remaining,
            "user_contributions": user_contributions,
            "per_category": {
                cat.value: {
                    "spent": self.budgets[cat].current_spent,
                    "limit": self.group_budget_limits[cat],
                    "remaining": self.budgets[cat].remaining(),
                    "over_limit": self.budgets[cat].is_over_limit()
                }
                for cat in Category
            }
        }

    # --- Optimization ---
    def suggest_optimizations(self) -> List[Dict]:
        suggestions = []
        for cat in Category:
            budget = self.budgets[cat]
            limit = self.group_budget_limits[cat]
            if budget.is_over_limit():
                overage = budget.current_spent - limit
                suggestions.append({
                    "type": "over_budget",
                    "category": cat.value,
                    "overage": overage,
                    "message": f"Category '{cat.value}' is over budget by ${overage:.2f}. Consider reducing spending."
                })
            elif limit > 0 and budget.current_spent / limit < 0.5:
                # Suggest reallocating unused budget
                unused = budget.remaining()
                suggestions.append({
                    "type": "under_utilized",
                    "category": cat.value,
                    "unused_amount": unused,
                    "message": f"Category '{cat.value}' has ${unused:.2f} unused. Consider reallocating to other categories."
                })

        # Cross-user optimization: identify top spenders per category
        category_spender_rankings = {}
        for cat in Category:
            user_spending = [
                (uid, user.get_total_spent(cat))
                for uid, user in self.users.items()
            ]
            user_spending.sort(key=lambda x: x[1], reverse=True)
            if user_spending and user_spending[0][1] > 0:
                category_spender_rankings[cat.value] = user_spending

        for cat_val, spenders in category_spender_rankings.items():
            top_spender_id, top_spent = spenders[0]
            if len(spenders) > 1 and top_spent > 0:
                avg_spent = sum(s for _, s in spenders) / len(spenders)
                if top_spent > 2 * avg_spent:
                    suggestions.append({
                        "type": "spending_disparity",
                        "category": cat_val,
                        "top_spender": top_spender_id,
                        "top_spent": top_spent,
                        "avg_spent": avg_spent,
                        "message": f"User '{top_spender_id}' spends {top_spent/avg_spent:.1f}x average in '{cat_val}'. Consider sharing tips or splitting bulk purchases."
                    })

        return suggestions


