class MultiAgentBudgetOptimizer:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budget_limits: Dict[Category, BudgetLimit] = {
            cat: BudgetLimit(category=cat, limit=0.0)
            for cat in Category
        }
        self.expense_counter = 0

    def add_user(self, user_id: str, name: str) -> bool:
        if user_id in self.users:
            return False
        self.users[user_id] = User(user_id, name)
        return True

    def remove_user(self, user_id: str) -> bool:
        if user_id not in self.users:
            return False
        del self.users[user_id]
        return True

    def add_expense(self, user_id: str, amount: float, category: Category, description: str = "") -> Optional[Expense]:
        if user_id not in self.users:
            return None
        if amount < 0:
            return None
        self.expense_counter += 1
        expense = Expense(
            id=f"exp_{self.expense_counter}",
            user_id=user_id,
            amount=amount,
            category=category,
            description=description
        )
        self.users[user_id].add_expense(expense)
        self._update_category_spending(category, amount)
        return expense

    def _update_category_spending(self, category: Category, amount: float) -> None:
        if category in self.budget_limits:
            self.budget_limits[category].current_spent += amount

    def set_budget_limit(self, category: Category, limit: float) -> bool:
        if limit < 0:
            return False
        if category not in self.budget_limits:
            self.budget_limits[category] = BudgetLimit(category=category, limit=limit)
        else:
            self.budget_limits[category].limit = limit
        return True

    def adjust_budget_limit(self, category: Category, new_limit: float) -> bool:
        return self.set_budget_limit(category, new_limit)

    def get_group_summary(self) -> dict:
        total_spent = sum(user.get_total_spent() for user in self.users.values())
        total_budget = sum(bl.limit for bl in self.budget_limits.values())
        remaining_budget = total_budget - total_spent
        user_contributions = {
            uid: {
                "name": user.name,
                "total_spent": user.get_total_spent(),
                "by_category": {cat.value: amount for cat, amount in user.get_spent_by_category().items()}
            }
            for uid, user in self.users.items()
        }
        category_breakdown = {
            cat.value: {
                "limit": self.budget_limits[cat].limit,
                "spent": self.budget_limits[cat].current_spent,
                "remaining": self.budget_limits[cat].limit - self.budget_limits[cat].current_spent,
                "over_limit": self.budget_limits[cat].current_spent > self.budget_limits[cat].limit
            }
            for cat in Category
        }
        return {
            "total_spent": total_spent,
            "total_budget": total_budget,
            "remaining_budget": remaining_budget,
            "user_contributions": user_contributions,
            "category_breakdown": category_breakdown
        }

    def get_optimization_suggestions(self) -> List[dict]:
        suggestions = []
        summary = self.get_group_summary()
        for cat, breakdown in summary["category_breakdown"].items():
            if breakdown["over_limit"]:
                over_amount = breakdown["spent"] - breakdown["limit"]
                suggestions.append({
                    "type": "over_limit",
                    "category": cat,
                    "message": f"Category '{cat}' is over budget by ${over_amount:.2f}. Consider reducing spending.",
                    "priority": "high"
                })
            elif breakdown["limit"] > 0 and breakdown["remaining"] / breakdown["limit"] > 0.3:
                suggestions.append({
                    "type": "underutilized",
                    "category": cat,
                    "message": f"Category '{cat}' has ${breakdown['remaining']:.2f} remaining ({breakdown['remaining']/breakdown['limit']*100:.1f}% unused). Consider reallocating to other categories.",
                    "priority": "medium"
                })
        # Suggest reallocating from underutilized to over-limit categories
        underutilized = [s for s in suggestions if s["type"] == "underutilized"]
        over_limit = [s for s in suggestions if s["type"] == "over_limit"]
        for over in over_limit:
            for under in underutilized:
                if over["category"] != under["category"]:
                    suggestions.append({
                        "type": "reallocate",
                        "from_category": under["category"],
                        "to_category": over["category"],
                        "message": f"Consider reallocating up to ${min(under['message'].split('$')[1].split('.')[0], over['message'].split('$')[1].split('.')[0])} from '{under['category']}' to '{over['category']}' to balance the budget.",
                        "priority": "medium"
                    })
                    break
        return suggestions

    def export_data(self) -> dict:
        return {
            "users": {uid: user.to_dict() for uid, user in self.users.items()},
            "budget_limits": {cat.value: bl.to_dict() for cat, bl in self.budget_limits.items()},
            "expense_counter": self.expense_counter
        }
